-- Spell power coefficient moves with the damage effect: 200002 no longer deals damage, 200027
-- (the new real-hit leg) does. Unit::SpellDamageBonusDone/-Taken look up spell_bonus_data by the
-- spell ID that's actually dealing the SCHOOL_DAMAGE, so the stale 200002 row must go too (it's
-- functionally inert now - 200002 has no SCHOOL_DAMAGE effect left - but stale/misleading).
DELETE FROM `spell_bonus_data` WHERE `entry` IN (200002, 200027);
INSERT INTO `spell_bonus_data` (`entry`, `direct_bonus`, `dot_bonus`, `ap_bonus`, `ap_dot_bonus`, `comments`) VALUES
(200027, 1.2, 0, 0, 0, 'Glacial Spike (Impact) - moved from 200002 by the 3-stage ramp redesign, docs/frost-mage-handoff.md');

-- New script class for the real-hit leg (icicle/Fingers-of-Frost consumption, Arctic Winds
-- shatter-cleave - see spell_mage_glacial_spike_impact in spell_mage.cpp). 200002's own
-- registration (spell_mage_glacial_spike) is unchanged - same script name, narrowed role.
DELETE FROM `spell_script_names` WHERE (`spell_id`, `ScriptName`) IN ((200027, 'spell_mage_glacial_spike_impact'));
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(200027, 'spell_mage_glacial_spike_impact');
